(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[206],{45265:function(e,a,i){Promise.resolve().then(i.bind(i,49420))},49420:function(e,a,i){"use strict";i.r(a),i.d(a,{default:function(){return s}});var r=i(3827);i(64090);var n=i(31725);let l={updatedAt:"2026-06-16",articleHeadline:"N11 K\xe2r Hesaplama: Komisyon, Hizmet Bedelleri, KDV ve Stopaj Dahil Net K\xe2r Rehberi",articleDescription:"N11 satıcıları i\xe7in komisyon, y\xfczde bazlı pazarlama/pazaryeri hizmet bedelleri, kargo, KDV ve stopaj dahil net k\xe2r hesaplama rehberi; g\xfcncel oranlar ve adım adım işlenmiş \xf6rnek.",blocks:[{type:"prose",heading:"N11’de Net K\xe2r Nasıl Hesaplanır?",paragraphs:["N11’i diğer pazaryerlerinden ayıran nokta, sabit bir platform hizmet bedeli yerine satış y\xfczdesi bazlı hizmet bedelleri kesmesidir. Bir N11 satışından elinize kalan tutar; satış fiyatından komisyon, pazarlama hizmet bedeli, pazaryeri hizmet bedeli, kargo, KDV ve stopaj d\xfcş\xfcl\xfcp ardından \xfcr\xfcn maliyeti \xe7ıkarılarak bulunur.","Y\xfczde bazlı yapı, fiyat arttık\xe7a hizmet bedellerinin de artması anlamına gelir; sabit \xfccretli platformların aksine d\xfcş\xfck fiyatlı \xfcr\xfcnde avantaj, y\xfcksek fiyatlı \xfcr\xfcnde ise dezavantaj yaratabilir. Bu rehber her kalemin ne olduğunu ve net k\xe2rınızı en \xe7ok hangilerinin etkilediğini a\xe7ıklar."]},{type:"feeTable",heading:"N11 Kesinti Kalemleri (2026)",intro:"N11’de sabit platform hizmet bedeli yoktur; bunun yerine satış y\xfczdesi bazlı iki hizmet bedeli kesilir.",columns:["Kalem","Oran / Tutar","A\xe7ıklama"],rows:[["Komisyon","Kategoriye g\xf6re %5 – %25","Satış tutarı \xfczerinden; kategoriye g\xf6re değişir."],["Komisyon KDV’si","%20 (sabit)","Komisyon %20 KDV’ye tabi bir hizmet bedelidir; bu komisyon KDV’si \xf6denecek KDV’nizden d\xfcş\xfcl\xfcr (indirilir) — net k\xe2ra etkisi br\xfct komisyon kadar değildir."],["Pazarlama Hizmet Bedeli","%1 + KDV","Satış tutarı \xfczerinden alınır; \xfczerine %20 KDV uygulanır."],["Pazaryeri Hizmet Bedeli","%0,67 + KDV","Satış tutarı \xfczerinden; \xfczerine %20 KDV uygulanır. Platformun işlem ve altyapı maliyetini karşılar."],["Kargo","Desiye g\xf6re değişir","\xdcr\xfcn\xfcn desi/ağırlığına ve anlaşmalı kargo barem fiyatına g\xf6re."],["Satış KDV’si","\xdcr\xfcn\xfcn ger\xe7ek oranı","Satış fiyatına dahildir; \xfcr\xfcn\xfcn kendi KDV oranından hesaplanır."],["Stopaj","%1","KDV hari\xe7 satış tutarının %1’i; gelir vergisi peşin kesintisi."]],note:"Hizmet bedelleri satış y\xfczdesi bazlıdır; sabit tutarlı bir PHB yoktur. Komisyon oranı kategoriye g\xf6re değişir — kesin oran i\xe7in yukarıdaki hesaplayıcıyı kullanın."},(0,i(77067).w)({platform:"n11",heading:"\xd6rnek: 299 TL’lik \xdcr\xfcnde Adım Adım Net K\xe2r",intro:"Aşağıdaki \xf6rnek %15 komisyon, 80 TL \xfcr\xfcn maliyeti ve 12 TL kargo varsayımıyladır. Platform hizmet bedeli, N11’in y\xfczde bazlı pazarlama ve pazaryeri hizmet bedellerinin toplamıdır.",salePrice:299,commissionRate:15,cost:80,cargoPrice:12,vatRate:20}),{type:"pitfalls",heading:"K\xe2rınızı Sessizce Yiyen Kalemler",intro:"N11 hesaplamasında en sık atlanan tuzaklar aşağıdadır.",items:[{title:"İki hizmet bedelini tek sanmak",body:"N11 hem pazarlama hizmet bedeli (%1 + KDV) hem de pazaryeri hizmet bedeli (%0,67 + KDV) keser; her ikisine de %20 KDV uygulanır. Sadece birini hesaba katmak kesintiyi eksik g\xf6sterir."},{title:"Y\xfczde bazlı bedelin y\xfcksek fiyatta b\xfcy\xfcmesi",body:"Sabit \xfccretli platformların aksine N11’in hizmet bedelleri fiyatla birlikte artar. Y\xfcksek fiyatlı \xfcr\xfcnlerde bu kalem k\xfc\xe7\xfcmsenmemelidir."},{title:"Komisyonun KDV etkisini atlamak",body:"Komisyon %20 KDV’ye tabidir; panel bu komisyon KDV’sini hesaplayıp \xf6denecek KDV’den d\xfcşer. Komisyonun KDV etkisini g\xf6z ardı etmek net k\xe2rı yanlış g\xf6sterir."},{title:"Stopajı atlamak",body:"Her satıştan KDV hari\xe7 tutarın %1’i stopaj olarak kesilir."},{title:"D\xfcş\xfck KDV’li \xfcr\xfcnde %20 varsaymak",body:"Satış ve maliyet KDV’si \xfcr\xfcn\xfcn ger\xe7ek oranındandır. %1 veya %10 KDV’li \xfcr\xfcnlerde “her şey %20” varsaymak \xf6denecek KDV’yi yanlış hesaplatır."}]},{type:"prose",heading:"Hizmet Bedelleri, KDV ve Stopajın Teknik Detayı",paragraphs:["N11’in iki hizmet bedeli satış y\xfczdesi \xfczerinden hesaplanır: pazarlama hizmet bedeli %1 ve pazaryeri hizmet bedeli %0,67. Her ikisi de hizmet bedeli niteliğinde olduğu i\xe7in \xfczerlerine %20 KDV uygulanır. Bunlar sabit tutarlı bir platform bedeli değil, satış fiyatına bağlı oransal kesintilerdir. Yukarıdaki hesaplayıcı bu kalemleri otomatik dikkate alır; \xf6rnek tablodaki “Platform hizmet bedeli” satırı bu bedellerin toplamını g\xf6sterir.","KDV tarafında ayrım şudur: satış KDV’si, maliyet KDV’si ve stopaj matrahı \xfcr\xfcn\xfcn ger\xe7ek KDV oranından (\xf6rn. %1, %10, %20) hesaplanır; komisyon ve pazaryerinin kendi hizmet bedellerinin KDV’si ise %20’dir. \xd6denecek KDV, satış KDV’nizden indirebileceğiniz gider KDV’lerinin d\xfcş\xfclmesiyle bulunur.","Stopaj, KDV hari\xe7 satış tutarının %1’idir: 299 TL’lik bir satışta (KDV %20 ise) stopaj = 299 / 1,20 \xd7 0,01 ≈ 2,49 TL olur ve yıl sonunda gelir vergisi beyannamenizde mahsup edilir."]},{type:"comparison",heading:"N11’i Diğer Pazaryerleriyle Karşılaştırın",intro:"Aynı \xfcr\xfcn\xfc farklı pazaryerlerinde satıyorsanız kesinti yapısı değişir. Her platformun k\xe2r hesaplayıcısıyla net k\xe2rınızı ayrı g\xf6r\xfcn.",rows:[{platform:"Trendyol",note:"Y\xfczde bazlı bedel yerine sabit platform hizmet bedeli kesilir (5,99 veya 13,19 TL).",href:"/trendyol-kar-hesaplama"},{platform:"Hepsiburada",note:"Sabit Marketplace HB + işlem bedeli (toplam 11,40 TL) kesilir.",href:"/hepsiburada-kar-hesaplama"},{platform:"Amazon",note:"Ayrı platform hizmet bedeli yoktur; ana kesinti referral komisyonudur.",href:"/amazon-turkiye-kar-hesaplama"}]}]},t={platform:"n11",name:"N11",slug:"n11-kar-hesaplama",color:"#7849b8",heroSubtitle:"Komisyon, kargo, pazarlama ve pazaryeri hizmet bedelleri, KDV ve stopaj dahil net k\xe2rınızı anında hesaplayın.",ctaText:"N11 mağazanızı bağlayın, sipariş ve finansal verilerinizi otomatik analiz edin.",formulaLines:(0,r.jsxs)(r.Fragment,{children:["Net K\xe2r = Satış Tutarı",(0,r.jsx)("br",{}),"\xa0\xa0- Komisyon (Satış \xd7 Komisyon Oranı)",(0,r.jsx)("br",{}),"\xa0\xa0- Kargo Maliyeti (Desi barem fiyatı)",(0,r.jsx)("br",{}),"\xa0\xa0- Pazarlama Hizmet Bedeli (%1 + KDV)",(0,r.jsx)("br",{}),"\xa0\xa0- Pazaryeri Hizmet Bedeli (%0,67 + KDV)",(0,r.jsx)("br",{}),"\xa0\xa0- \xdcr\xfcn Maliyeti (Tedarik + Ambalaj)",(0,r.jsx)("br",{}),"\xa0\xa0- \xd6denecek KDV (Satış KDV - Gider KDV'leri)",(0,r.jsx)("br",{}),"\xa0\xa0- Stopaj (Satış / 1.20 \xd7 0.01)"]}),formulaNote:(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("strong",{style:{color:"inherit"},children:"\xd6nemli:"})," N11 sabit platform hizmet bedeli yerine satış y\xfczdesi bazlı iki hizmet bedeli kesilir: %1 pazarlama hizmet bedeli ve %0,67 pazaryeri hizmet bedeli (her ikisine de %20 KDV uygulanır). Satış ve maliyet KDV'si \xfcr\xfcn\xfcn ger\xe7ek KDV oranı \xfczerinden, pazaryerinin kendi hizmet bedellerinin KDV'si ise %20 \xfczerinden hesaplanır."]}),faq:[{q:"N11 k\xe2r hesaplama nasıl yapılır?",a:"N11'de k\xe2r hesaplamak i\xe7in satış fiyatından komisyon, kargo maliyeti, pazarlama hizmet bedeli (%1 + KDV), pazaryeri hizmet bedeli (%0,67 + KDV), \xfcr\xfcn maliyeti, KDV ve stopaj d\xfcş\xfclmelidir. Form\xfcl: Net K\xe2r = Satış - Komisyon - Kargo - Pazarlama HB - Pazaryeri HB - Maliyet - KDV - Stopaj."},{q:"N11 komisyon oranları ne kadar?",a:"N11 komisyon oranları kategoriye g\xf6re %5 ile %25 arasında değişir. Bunun yanında her satıştan %1 + KDV pazarlama hizmet bedeli ve %0,67 + KDV pazaryeri hizmet bedeli kesilir."},{q:"N11 pazarlama hizmet bedeli nedir?",a:"N11 her satıştan satış fiyatının %1'i oranında pazarlama hizmet bedeli keser. Bu bedel satış tutarı \xfczerinden hesaplanır ve hizmet bedeli niteliğinde olduğu i\xe7in \xfczerine %20 KDV uygulanır."},{q:"N11 pazaryeri hizmet bedeli nedir?",a:"N11 pazaryeri hizmet bedeli satış fiyatının %0,67'si + KDV olarak hesaplanır. Bu bedel platformun işlem ve altyapı maliyetlerini karşılar."},{q:"N11 stopaj oranı ne kadar?",a:"N11 stopaj oranı KDV hari\xe7 satış tutarının %1'idir. Form\xfcl: Stopaj = Satış / 1,20 \xd7 0,01. Yıllık gelir vergisi beyannamenizden mahsup edilir."},{q:"N11 KDV hesaplaması nasıl yapılır?",a:"Satış ve maliyet KDV'si \xfcr\xfcn\xfcn ger\xe7ek KDV oranı \xfczerinden, N11'in komisyon/hizmet bedeli KDV'si ise %20 \xfczerinden hesaplanır. Satış KDV'sinden gider KDV'leri d\xfcş\xfclerek \xf6denecek KDV bulunur."},{q:"N11'de Trendyol'dan farkı ne?",a:"N11'de sabit platform hizmet bedeli (PHB) yerine satış y\xfczdesi bazlı hizmet bedelleri kesilir: %1 + KDV pazarlama HB + %0,67 + KDV pazaryeri HB. Trendyol'da ise sabit tutarlı PHB uygulanır."},{q:"NİTRU ile t\xfcm platformları y\xf6netebilir miyim?",a:"Evet, NİTRU Trendyol, Hepsiburada, Amazon, N11, \xc7i\xe7eksepeti ve Pazarama dahil 6 pazaryerini destekler. T\xfcm mağazalarınızın k\xe2r analizini tek panelden yapabilirsiniz."}],blogLinks:[{href:"/blog/eticaret-kdv-stopaj-rehberi",label:"KDV ve Stopaj Rehberi"},{href:"/blog",label:"T\xfcm Blog Yazıları"}],content:l};function s(){return(0,r.jsx)(n.Z,{config:t})}}},function(e){e.O(0,[6669,5250,2406,6095,3897,9778,9952,7774,6676,9419,581,6972,8214,7447,3138,2971,8069,1744],function(){return e(e.s=45265)}),_N_E=e.O()}]);